#include <string>
#include <string_view>

std::string trim_left(std::string_view s, std::string_view chars = " \t\n")
{
    std::size_t i{ 0 };
    while (i < s.size() && chars.find(s[i]) != std::string_view::npos) ++i;
    return std::string(s.substr(i));
}

std::string trim_left(std::string_view s, char c)
{
    return trim_left(s, std::string_view(&c, 1));
}

std::string trim_right(std::string_view s, std::string_view chars = " \t\n")
{
    std::size_t end{ s.size() };
    while (end > 0 && chars.find(s[end - 1]) != std::string_view::npos) --end;
    return std::string(s.substr(0, end));
}

std::string trim_right(std::string_view s, char c)
{
    return trim_right(s, std::string_view(&c, 1));
}

std::string trim(std::string_view s, std::string_view chars = " \t\n")
{
    return trim_right(trim_left(s, chars), chars);
}

std::string trim(std::string_view s, char c)
{
    return trim(s, std::string_view(&c, 1));
}

unitTests:
TEST("the defaults remove whitespace") {
    CHECK_EQ(trim_left("  hello "), std::string("hello "));
    CHECK_EQ(trim_right("  hello \n\t"), std::string("  hello"));
    CHECK_EQ(trim("\t\n hello world \n"), std::string("hello world"));
}
TEST("a set of characters") {
    CHECK_EQ(trim_left("xyxhixy", "xy"), std::string("hixy"));
    CHECK_EQ(trim_right("xyxhixy", "xy"), std::string("xyxhi"));
    CHECK_EQ(trim("--==title==--", "-="), std::string("title"));
}
TEST("a single character") {
    CHECK_EQ(trim_left("000120", '0'), std::string("120"));
    CHECK_EQ(trim_right("000120", '0'), std::string("00012"));
    CHECK_EQ(trim("**bold**", '*'), std::string("bold"));
}
TEST("edge cases from the page") {
    CHECK_EQ(trim_left("abc", ""), std::string("abc"));
    CHECK_EQ(trim("  abc  ", ""), std::string("  abc  "));
    CHECK_EQ(trim_left("xxx", "x"), std::string(""));
    CHECK_EQ(trim("xxx", 'x'), std::string(""));
    CHECK_EQ(trim(""), std::string(""));
    CHECK_EQ(trim_right("   "), std::string(""));
    CHECK_EQ(trim(" \r\n"), std::string("\r"));
}

